# apply_corp.py — knexm.com/corp 특전 페이지 만들기
# C:\knexm-site 폴더에 넣고 실행:  python apply_corp.py
import base64, os, sys
here = os.path.dirname(os.path.abspath(__file__))
if not os.path.exists(os.path.join(here, 'index.html')):
    print('❌ C:\\knexm-site 폴더(홈페이지 index.html이 있는 곳)에 넣고 실행하세요. 아무것도 저장하지 않았어요.'); sys.exit(1)
FILES = {
    'corp/cover.jpg': '',
    'corp/index.html': '',
    'corp/files/form-01.docx': '',
    'corp/files/form-02.docx': '',
    'corp/files/form-03.docx': '',
    'corp/files/form-04.docx': '',
    'corp/files/form-05.docx': '',
    'corp/files/form-06.docx': '',
    'corp/files/form-07.docx': '',
    'corp/files/forms.zip': '',
    'corp/files/ledger-example.xlsx': '',
    'corp/files/ledger.xlsx': '',
}
for rel, data in FILES.items():
    out = os.path.join(here, *rel.split("/"))
    os.makedirs(os.path.dirname(out), exist_ok=True)
    open(out, "wb").write(base64.b64decode(data))
    print("✔", rel)
print('완료: 올린 뒤 https://knexm.com/corp 에서 확인하세요')
